type IconComponent = (props: SVGProps<SVGSVGElement>) => ReactElement;

type Reason = {
  id: number;
  title: string;
  Icon: IconComponent;
};

export default function ParentsSolutionsHero() {
  const { t } = useTranslation();
  
  const reasons: Reason[] = [
    {
      id: 1,
      title: t("parents_solutions.solutions[0].title"),
      Icon: TeacherBoardIcon,
    },
    {
      id: 2,
      title: t("parents_solutions.solutions[1].title"),
      Icon: TargetCheckIcon,
    },
    {
      id: 3,
      title: t("parents_solutions.solutions[2].title"),
      Icon: SpeakingHeadIcon,
    },
    {
      id: 4,
      title: t("parents_solutions.solutions[3].title"),
      Icon: ChartGrowthIcon,
    },
    {
      id: 5,
      title: t("parents_solutions.solutions[4].title"),
      Icon: GraduationCapIcon,
    },
  ];
  const scrollItems = [...reasons, ...reasons];

  return (
    <section className="w-full bg-white px-5 pb-16 pt-8 sm:px-8 sm:pb-20 sm:pt-10 lg:pb-24">
      <div className="mx-auto max-w-360 px-6 sm:px-8 text-center">
        <h1 className="text-4xl font-bold text-(--brand-dark) md:text-5xl lg:text-5xl">
          {t("parents_solutions.hero_title")}
        </h1>

        <p className="mt-4 text-base text-(--brand-dark) md:text-lg">
          {t("parents_solutions.hero_subtitle")}
        </p>
      </div>

      <div className="relative left-1/2 mt-8 w-screen -translate-x-1/2 sm:mt-10 lg:mt-12">
        <div className="overflow-hidden">
          <div
            className="animate-scroll gap-6"
            style={{ animationDuration: "60s" }}
          >
            {scrollItems.map((reason, index) => {
              const Icon = reason.Icon;
              const iconSizeClass =
                reason.id === 2
                  ? "h-6 w-6 sm:h-7 sm:w-7"
                  : "h-9 w-11 sm:h-10 sm:w-12";

              return (
                <article
                  key={`${reason.id}-${index}`}
                  className="relative w-75 shrink-0 rounded-[34px] border border-(--brand-red) bg-white px-6 pb-6 pt-6 sm:min-h-51.5 sm:w-85 sm:rounded-[40px] sm:px-7 sm:pb-7 sm:pt-6"
                >
                  <div className="absolute left-0 top-1/2 h-13 w-1.5 -translate-y-1/2 rounded-r-full bg-(--brand-red)" />

                  <div className="grid h-12 w-12 place-items-center rounded-full bg-(--brand-red) text-white sm:h-13.5 sm:w-13.5">
                    <Icon className={iconSizeClass} aria-hidden="true" />
                  </div>

                  <h3 className="mt-4 text-2xl leading-none font-bold text-(--brand-dark)">
                    {reason.title}
                  </h3>
                </article>
              );
            })}
          </div>
        </div>
      </div>
    </section>
  );
}

